// Statut tunnels (workflow « Statut tunnels et VPN ») : v2026.11.12-7 : première version
// Même code que le nœud check_tunnels_vpn du rapport du matin, appelé à la demande par la carte
// « Accès externe » du dashboard (Webhook GET /webhook/statut-tunnels, relais Nginx /n8n-tunnels/).
// 1) Tunnels Cloudflare : état de chaque tunnel (healthy, degraded, down, inactive) et nombre de connexions,
//    lus avec un jeton API en lecture seule (permission Account, Cloudflare Tunnel, Read).
// 2) Passerelles pfSense : état, perte et délai de chaque passerelle (API REST v2 /status/gateways).
//    Les passerelles VPN sont reconnues par leur nom (NORD ou VPN).
// Sortie : 1 item { tunnels, tunnels_erreur, passerelles, passerelles_erreur }

const CLOUDFLARE = {
  compte: 'A_REMPLIR',
  jeton: 'A_REMPLIR',
};
const PFSENSE = {
  url: 'https://IP_PRIVEE_2:PORT_2',
  cle: 'A_REMPLIR',   // la même clé que dans le nœud check_pfsense_logs
};

const sortie = { verifie_a: new Date().toISOString(), tunnels: [], tunnels_erreur: null, passerelles: [], passerelles_erreur: null };

// ---- 1) Tunnels Cloudflare ----
if (CLOUDFLARE.jeton.startsWith('COLLER_')) {
  sortie.tunnels_erreur = 'jeton Cloudflare absent dans le nœud check_tunnels_vpn';
} else {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.cloudflare.com/client/v4/accounts/' + CLOUDFLARE.compte + '/cfd_tunnel?is_deleted=false',
      headers: { Authorization: 'Bearer ' + CLOUDFLARE.jeton },
      json: true,
    });
    if (!r.success) {
      sortie.tunnels_erreur = 'réponse Cloudflare en échec : ' + JSON.stringify(r.errors || r).slice(0, 150);
    } else {
      sortie.tunnels = (r.result || []).map(t => ({
        nom: t.name,
        etat: t.status,                                   // healthy, degraded, down, inactive
        connexions: (t.connections || []).length,
        centres: [...new Set((t.connections || []).map(c => c.colo_name).filter(Boolean))],
        actif_depuis: t.conns_active_at || null,
      }));
    }
  } catch (e) {
    sortie.tunnels_erreur = 'appel Cloudflare impossible : ' + String(e.message).slice(0, 150);
  }
}

// ---- 2) Passerelles pfSense ----
const texte = v => (v == null ? '' : String(v));
const nombre = v => { const n = parseFloat(texte(v).replace(',', '.')); return isNaN(n) ? null : n; };
if (PFSENSE.cle.startsWith('COLLER_')) {
  sortie.passerelles_erreur = 'clé API pfSense absente dans le nœud check_tunnels_vpn';
} else {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: PFSENSE.url + '/api/v2/status/gateways',
      headers: { 'X-API-Key': PFSENSE.cle, Accept: 'application/json' },
      skipSslCertificateValidation: true,
      json: true,
    });
    const liste = Array.isArray(r.data) ? r.data : [];
    if (!liste.length) sortie.passerelles_erreur = 'aucune passerelle dans la réponse : ' + JSON.stringify(r).slice(0, 150);
    sortie.passerelles = liste.map(g => {
      const nom = texte(g.name || g.gateway || g.monitorip);
      return {
        nom,
        vpn: /nord|vpn/i.test(nom),
        etat: texte(g.status),                            // online, down...
        sous_etat: texte(g.substatus),                    // none, highloss, highdelay...
        perte_pct: nombre(g.loss),
        delai_ms: nombre(g.delay),
        ip_surveillee: texte(g.monitorip),
      };
    });
  } catch (e) {
    sortie.passerelles_erreur = 'appel pfSense impossible : ' + String(e.message).slice(0, 150);
  }
}

return [{ json: sortie }];
